public static int[] sort(int[] a) {
    int[] b = new int[a.length];
    for (int i = 0; i < a.length; ++i) {
        int j = 0;
        while (j < i && a[i] >= b[j]) ++j;
        for (int k = i - 1; k >= j; --k) b[k + 1] = b[k];
        b[j] = a[i];
    }
    return b;
}
